#!/usr/bin/env node
// Local audit of the built dist/ output. Produces reports/audit.json and a
// markdown matrix (AUDIT.md section is generated by: node scripts/qa/audit.cjs --md > reports/audit-matrix.md).
// Usage: node scripts/qa/audit.cjs [--md]   (after `npm run build`). Local only — not production verification.
const fs = require('fs');
const path = require('path');
const dist = path.join(process.cwd(), 'dist');
const LOCALES = ['ru', 'th', 'he'];
const rows = [];

function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const f = path.join(d, e.name);
    if (e.isDirectory()) { if (e.name !== '_astro' && e.name !== 'images') walk(f); }
    else if (e.name.endsWith('.html')) rows.push(analyse(f));
  }
}
const strip = (h) => h.replace(/<script[\s\S]*?<\/script>/g, ' ').replace(/<style[\s\S]*?<\/style>/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/g, ' ');
function analyse(file) {
  const html = fs.readFileSync(file, 'utf8');
  let url = file.slice(dist.length).replace(/index\.html$/, '');
  const seg = url.split('/')[1];
  const locale = LOCALES.includes(seg) ? seg : 'en';
  const rest = locale === 'en' ? url : url.slice(locale.length + 1);
  const type = rest === '/' ? 'home' : rest.startsWith('/services/') ? 'service' : rest.startsWith('/locations/') ? (rest === '/locations/' ? 'locations-index' : 'location') : rest.startsWith('/projects/') ? (rest === '/projects/' ? 'projects-index' : 'project') : rest.startsWith('/journal/') ? (rest === '/journal/' ? 'journal-index' : 'article') : rest.replace(/\//g, '') || 'page';
  const main = (html.match(/<main[\s\S]*?<\/main>/) || [html])[0];
  const text = strip(main);
  const words = locale === 'th' ? (text.replace(/\s+/g, '').length / 6) | 0 : (text.match(/[\p{L}\p{N}'’-]+/gu) || []).length;
  const title = (html.match(/<title>([^<]*)<\/title>/) || [])[1] || '';
  const desc = (html.match(/<meta name="description" content="([^"]*)"/) || [])[1] || '';
  const h1 = (html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/) || [])[1] || '';
  const ld = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => { try { return JSON.parse(m[1]); } catch { return null; } });
  const types = new Set();
  const visit = (o) => { if (!o || typeof o !== 'object') return; if (o['@type']) [].concat(o['@type']).forEach((t) => types.add(t)); Object.values(o).forEach(visit); };
  ld.forEach(visit);
  const latin = (text.match(/[A-Za-z]/g) || []).length, all = (text.match(/\p{L}/gu) || []).length || 1;
  return {
    url, locale, type, title, titleLen: title.length, descLen: desc.length, h1: strip(h1).trim(),
    h1Count: (html.match(/<h1[ >]/g) || []).length, h2: (main.match(/<h2[ >]/g) || []).length,
    words, canonical: /<link rel="canonical"/.test(html), hreflang: (html.match(/<link rel="alternate" hreflang=/g) || []).length,
    dir: (html.match(/<html[^>]*dir="(\w+)"/) || [])[1] || 'ltr', jsonld: [...types].sort().join(','),
    noindex: /name="robots"[^>]*noindex/.test(html), pricing: /pricing|price/i.test(main) && /THB|฿|base/i.test(main),
    latinPct: Math.round((latin / all) * 100), faq: /faq|frequently/i.test(main),
    links: (main.match(/<a [^>]*href="\//g) || []).length,
  };
}
walk(dist);
rows.sort((a, b) => a.url.localeCompare(b.url));
fs.mkdirSync('reports', { recursive: true });
fs.writeFileSync('reports/audit.json', JSON.stringify(rows, null, 2));
if (process.argv.includes('--md')) {
  console.log('| URL | Locale | Type | Title len | Desc len | H1 | Words | Hreflang | Dir | JSON-LD | Latin% | Links |');
  console.log('|---|---|---|---|---|---|---|---|---|---|---|---|');
  for (const r of rows) console.log(`| ${r.url} | ${r.locale} | ${r.type} | ${r.titleLen} | ${r.descLen} | ${r.h1Count} | ${r.words} | ${r.hreflang} | ${r.dir} | ${r.jsonld} | ${r.latinPct} | ${r.links} |`);
} else console.log(`Audited ${rows.length} pages -> reports/audit.json`);
